<script setup lang="ts">
import {ref,reactive,computed,watch,onMounted} from 'vue';
import {clientMissing,money,type Client,type Product,type Page,type Currency,type Quote,type Order} from '@briochett/contracts';
import {useAuth} from '../stores/auth';
import {api,ApiFailure,errorMessage,readDraft,writeDraft,removeDraft} from '../api';
import AppModal from './AppModal.vue';import ClientSelector from './ClientSelector.vue';import ClientForm from './ClientForm.vue';import Pagination from './Pagination.vue';
const props=defineProps<{clientId?:string;visitId?:string}>(),emit=defineEmits<{close:[];saved:[order:Order]}>(),auth=useAuth(),key='briochett:order:'+auth.user!.id;
type Draft={clientId:string;currency:Currency;quantities:Record<string,number>;notes:string;key:string;visitId?:string;attempt:any|null;quote:Quote|null};
const blank=():Draft=>({clientId:props.clientId||'',currency:'USD',quantities:{},notes:'',key:crypto.randomUUID(),visitId:props.visitId,attempt:null,quote:null}),restored=readDraft<Draft|null>(key,null),draft=reactive<Draft>(restored||blank());
const stage=ref<'client'|'completion'|'products'|'review'>(draft.attempt?'review':'client'),client=ref<Client|null>(null),products=ref<Page<Product>>({items:[],total:0,page:1,pageSize:20}),page=ref(1),busy=ref(false),error=ref(''),storageError=ref(false),notice=ref(restored?'Se recuperó el borrador de tu pedido.':'');
const title=computed(()=>({client:'Seleccionar cliente',completion:'Completar datos del cliente',products:'Registrar pedido',review:'Revisar pedido'}[stage.value]));
watch(draft,()=>{storageError.value=!writeDraft(key,draft);},{deep:true,flush:'sync'});
async function select(c:Client){client.value=c;draft.clientId=c.id;stage.value=auth.user?.role==='vendedor'&&clientMissing(c).length?'completion':'products';error.value='';}
async function loadProducts(){try{products.value=await api<Page<Product>>('/products?active=true&page='+page.value);}catch(e){error.value=errorMessage(e);}}
watch(page,loadProducts);
onMounted(async()=>{await loadProducts();if(draft.clientId)try{const c=await api<Client>('/clients/'+draft.clientId);client.value=c;if(!draft.attempt)await select(c);}catch(e){error.value=errorMessage(e);stage.value='client';}});
const units=computed(()=>Object.values(draft.quantities).reduce((a,b)=>a+(Number(b)||0),0));
function adjust(id:string,amount:number){draft.quantities[id]=Math.max(0,Math.min(100000,(Number(draft.quantities[id])||0)+amount));}
async function review(){error.value='';busy.value=true;try{const items=Object.entries(draft.quantities).filter(([,quantity])=>quantity>0).map(([productId,quantity])=>({productId,quantity:Number(quantity)}));draft.quote=await api<Quote>('/orders/quote',{method:'POST',body:{clientId:draft.clientId,currency:draft.currency,items}});stage.value='review';}catch(e){error.value=errorMessage(e);if(e instanceof ApiFailure&&e.code==='CLIENT_INCOMPLETE'){client.value=await api<Client>('/clients/'+draft.clientId);stage.value='completion';}}finally{busy.value=false;}}
async function confirm(){if(!draft.quote)return;error.value='';busy.value=true;draft.attempt??={clientId:draft.clientId,currency:draft.currency,items:draft.quote.items.map(i=>({productId:i.productId,quantity:i.quantity})),quoteVersion:draft.quote.version,notes:draft.notes,visitId:draft.visitId||null};
try{const order=await api<Order>('/orders',{method:'POST',body:draft.attempt,headers:{'Idempotency-Key':draft.key}});removeDraft(key);emit('saved',order);}catch(e){error.value=errorMessage(e);if(e instanceof ApiFailure&&e.status>=400&&e.status<500&&e.code!=='IDEMPOTENCY_CONFLICT'){draft.attempt=null;if(e.code==='QUOTE_CHANGED')await review();if(e.code==='CLIENT_INCOMPLETE'){client.value=await api<Client>('/clients/'+draft.clientId);stage.value='completion';}}}finally{busy.value=false;}}
function discard(){if(draft.attempt)return;removeDraft(key);Object.assign(draft,blank());client.value=null;stage.value='client';notice.value='';}
</script>
<template><AppModal :title="title" :wide="stage==='products'||stage==='review'" :busy="busy" @close="emit('close')"><p v-if="notice" class="notice">{{notice}}</p><p v-if="storageError" class="notice error">No se pudo guardar el borrador en este dispositivo. Mantén esta ventana abierta.</p><p v-if="error" class="notice error" role="alert">{{error}}</p>
<ClientSelector v-if="stage==='client'" @select="select" />
<ClientForm v-else-if="stage==='completion'&&client" :key="client.id" :client="client" completion @busy="busy=$event" @saved="select" @cancel="stage='client'" />
<div v-else-if="stage==='products'" class="stack"><div class="split"><div><small class="muted">Cliente</small><h3>{{client?.name}}</h3></div><button class="secondary" @click="stage='client'">Buscar o cambiar cliente</button></div><label>Moneda del pedido<select v-model="draft.currency"><option value="USD">Dólares · USD</option><option value="COP">Pesos colombianos · COP</option><option value="VES">Bolívares · VES</option></select></label><p class="muted small">Precios base en USD. El resumen aplicará la tasa vigente de la moneda elegida.</p><div v-for="p in products.items" :key="p.id" class="product-line"><div><strong>{{p.name}}</strong><small>{{p.sku}} · {{money(p.priceUsd,'USD')}} / unidad</small></div><div class="quantity"><button class="secondary" :aria-label="'Restar '+p.name" @click="adjust(p.id,-1)">−</button><input v-model.number="draft.quantities[p.id]" :aria-label="'Cantidad de '+p.name" type="number" min="0" max="100000" step="1" placeholder="0" /><button class="secondary" :aria-label="'Sumar '+p.name" @click="adjust(p.id,1)">+</button><button class="secondary" :aria-label="'Agregar seis '+p.name" @click="adjust(p.id,6)">+6</button></div></div><Pagination :page="page" :total="products.total" @change="page=$event" /><p v-if="!products.items.length" class="empty">No hay productos activos. Administración debe agregar productos al catálogo.</p><label>Observaciones<textarea v-model="draft.notes" maxlength="1000"></textarea></label><div class="summary-bar"><span>Unidades seleccionadas</span><strong>{{units}}</strong></div><div class="actions"><button :disabled="busy||units<1" @click="review">{{busy?'Calculando…':'Revisar pedido'}}</button><button class="secondary" @click="emit('close')">Guardar borrador y cerrar</button></div></div>
<div v-else-if="stage==='review'&&draft.quote" class="stack"><h3>{{client?.name||'Cliente seleccionado'}}</h3><p>{{draft.currency}} · Tasa: 1 USD = {{draft.quote.rate}} {{draft.currency}}</p><div v-for="line in draft.quote.items" :key="line.productId" class="review-line"><div><strong>{{line.name}}</strong><small>{{line.quantity}} × {{money(line.unitPrice,draft.currency)}}</small></div><strong>{{money(line.subtotal,draft.currency)}}</strong></div><div class="summary-bar"><span>{{draft.quote.units}} unidades · Total</span><strong>{{money(draft.quote.total,draft.currency)}}</strong></div><p class="muted small">Al registrar, el pedido quedará pendiente de validación administrativa. Los precios y la tasa de este pedido se conservarán.</p><p v-if="draft.attempt" class="notice">Se está resolviendo este registro. Puedes reintentar sin crear otro pedido.</p><div class="actions"><button :disabled="busy" @click="confirm">{{busy?'Registrando…':draft.attempt?'Reintentar registro':'Confirmar y registrar pedido'}}</button><button v-if="!draft.attempt" class="secondary" :disabled="busy" @click="stage='products'">Editar cantidades</button><button v-else class="secondary" :disabled="busy" @click="emit('close')">Cerrar y conservar intento</button></div></div>
<button v-if="!draft.attempt&&stage!=='completion'" class="text-button danger" :disabled="busy" @click="discard">Descartar borrador y empezar de nuevo</button></AppModal></template>
